// Differential check against the Lean model in formal/lean. The corpus is generated by
// formal/lean/Vectors.lean from executable deciders proved equal to the declarative
// relations (APS.Scope.covers?_iff, APS.Spend.le?_iff). It is exhaustive over a small
// universe, so a pass means the SDK agrees with the model on these cases, not in general.

import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import {
  REPUTATION_PROFILE_V1,
  REVERSIBILITY_PROFILE_V1,
  SCOPE_PROFILE_V1,
  VALUES_PROFILE_V1,
  compareAuthority,
  grantsAreCanonical,
  scopeGrantCovers,
  scopeNarrows,
} from '../../src/v2/authority-delegation/index.js'
import type { AuthorityVectorV1, SpendFacetV1 } from '../../src/v2/authority-delegation/index.js'

const corpus = JSON.parse(readFileSync(new URL('./fixtures/lean-correspondence.json', import.meta.url), 'utf8'))

function vector(spend: SpendFacetV1, remaining: number): AuthorityVectorV1 {
  return {
    scope: { profile: SCOPE_PROFILE_V1, grants: ['commerce:*'] },
    spend,
    depth: { remaining },
    time: { not_before: '2026-07-18T22:00:00.000Z', not_after: '2026-07-18T23:00:00.000Z' },
    reputation: { profile: REPUTATION_PROFILE_V1, ceiling: 80 },
    values: { profile: VALUES_PROFILE_V1, required: ['F-001', 'F-003'] },
    reversibility: { profile: REVERSIBILITY_PROFILE_V1, ceiling: 'compensable' },
  }
}

test('lean corpus is present and non-trivial', () => {
  assert.equal(corpus.generator, 'formal/lean/Vectors.lean')
  for (const key of ['scope_covers', 'scope_canonical', 'scope_narrows', 'spend']) {
    assert.ok(Array.isArray(corpus[key]) && corpus[key].length > 0, key)
    assert.ok(corpus[key].some((c: Record<string, unknown>) => Object.values(c).includes(true)), `${key} has a true case`)
    assert.ok(corpus[key].some((c: Record<string, unknown>) => Object.values(c).includes(false)), `${key} has a false case`)
  }
})

test('scopeGrantCovers agrees with APS.Scope.Covers', () => {
  const bad = corpus.scope_covers.filter((c: { parent: string, child: string, covers: boolean }) =>
    scopeGrantCovers(c.parent, c.child) !== c.covers)
  assert.deepEqual(bad, [])
})

test('grantsAreCanonical agrees with sorted plus APS.Scope.Irredundant', () => {
  const bad = corpus.scope_canonical.filter((c: { grants: string[], canonical: boolean }) =>
    grantsAreCanonical(c.grants) !== c.canonical)
  assert.deepEqual(bad, [])
})

test('scopeNarrows agrees with APS.Scope.Within, canonical parents and any child', () => {
  const bad = corpus.scope_narrows.filter((c: { parent: string[], child: string[], narrows: boolean }) =>
    scopeNarrows(c.parent, c.child) !== c.narrows)
  assert.deepEqual(bad, [])
})

test('compareAuthority spend branch agrees with APS.Spend.Le', () => {
  // Every facet other than spend is identical and depth is a valid step, so only spend
  // can produce a failure.
  const bad = corpus.spend.filter((c: { parent: SpendFacetV1, child: SpendFacetV1, contained: boolean }) => {
    const failures = compareAuthority(vector(c.parent, 3), vector(c.child, 2))
    assert.ok(failures.every(f => f.facet === 'spend'), JSON.stringify(failures))
    return (failures.length === 0) !== c.contained
  })
  assert.deepEqual(bad, [])
})
